describe("safe PDF provider diagnostics", () => {
  it.each([400, 401, 403, 404, 429, 500, 503])(
    "reports HTTP %i without provider payloads",
    (status) => {
      const message = pdfAiFailureReason(
        new Error(`Google request failed (HTTP ${status}): PRIVATE_PROVIDER_BODY synthetic-secret`),
      );
      expect(message).toContain(`HTTP ${status}`);
      expect(message).not.toContain("PRIVATE_PROVIDER_BODY");
      expect(message).not.toContain("synthetic-secret");
    },
  );

  it("keeps quota distinct from missing or rejected credentials", () => {
    expect(pdfAiFailureReason(new Error("Google request failed (HTTP 429)"))).toMatch(
      /rate-limited or out of quota/,
    );
    expect(pdfAiFailureReason(new Error("The default AI (google) has no API key."))).toMatch(
      /agent API setup alone is not used by Raw/,
    );
    expect(pdfAiFailureReason({ statusCode: 401, message: "PRIVATE" })).toMatch(
      /rejected credentials/,
    );
  });

  it("unwraps internal preview causes, without returning their content", () => {
    expect(
      pdfAiFailureReason(
        new Error("Preview failed", { cause: { status: 429, message: "PRIVATE" } }),
      ),
    ).toMatch(/HTTP 429/);
  });

  it.each([
    ["Google structured response failed schema validation", "does not match"],
    ["Google structured output schema is unsupported", "cannot send"],
    ["Google structured response is not valid JSON", "invalid JSON"],
    ["Google response is invalid or incomplete", "incomplete or refused"],
    ["Google transport failed", "could not be reached"],
  ])("classifies %s without request or response content", (message, expected) => {
    expect(pdfAiFailureReason(new Error(message))).toContain(expected);
  });

  it("never forwards arbitrary exception text", () => {
    expect(pdfAiFailureReason(new Error("PRIVATE_DOC sk-synthetic-key"))).toBe(
      "Check the configured default AI and credentials",
    );
    expect(pdfAiFailureReason(undefined)).toBe("Check the configured default AI and credentials");
  });
});
import {
  BLOCK_SPECS,
  DEFAULT_SETTINGS,
  PALETTE_BLOCK_KINDS,
  parseBlockParams,
  ProductScope,
  type FileStore,
  type LlmClient,
  type Settings,
} from "@reqflow/core";
import type { BlockPreview } from "@reqflow/core/ipc";
import { NO_AGENT_SERVICES, type BlockContext, type BlockRegistry } from "@reqflow/engine";
import { z } from "zod";
import { pdfAiFailureReason } from "../../../../packages/blocks/src/raw/ai-error";
import { ReqflowError } from "./dispatch";

const Request = z.object({
  kind: z.enum(PALETTE_BLOCK_KINDS),
  params: z.record(z.string(), z.unknown()),
  scope: ProductScope,
});

const unavailable = (what: string) => () => {
  throw new Error(`${what} isn't available in a preview; run the flow instead`);
};

export interface PreviewBlockDeps {
  settings?: Settings;
  llm?: LlmClient;
}

export class AiPreviewError extends Error {
  constructor(error?: unknown) {
    super(`AI provider failed to generate a preview response. ${pdfAiFailureReason(error)}.`, {
      cause: error,
    });
    this.name = "AiPreviewError";
  }
}

function safePreviewLlm(client: LlmClient): LlmClient {
  return {
    async generateText(options) {
      try {
        return await client.generateText(options);
      } catch (error) {
        throw new AiPreviewError(error);
      }
    },
    async generateObject(options) {
      try {
        return await client.generateObject(options);
      } catch (error) {
        throw new AiPreviewError(error);
      }
    },
  };
}

/**
 * Runs a block without inputs on its own (blocks.preview). Electron-free so it can be unit-tested.
 * The request comes from the renderer, so it is validated like any untrusted input.
 */
export async function previewBlock(
  registry: BlockRegistry,
  files: FileStore,
  request: unknown,
  deps?: PreviewBlockDeps,
): Promise<BlockPreview> {
  const { kind, params: rawParams, scope } = Request.parse(request);
  const spec = BLOCK_SPECS[kind];
  const params = parseBlockParams(kind, rawParams);
  if (spec.ports(params).inputs.length > 0) {
    throw new ReqflowError(
      "invalid_input",
      `${spec.label} takes inputs, so its data only exists inside a run`,
    );
  }
  if (kind === "research") {
    throw new ReqflowError(
      "not_implemented",
      "Research collection is unavailable in preview; run the flow to apply access gates, budgets and provenance persistence.",
    );
  }
  if (!registry.has(kind)) {
    throw new ReqflowError("not_implemented", `The ${spec.label} block isn't built yet`);
  }

  const logs: string[] = [];
  const settings: Settings = {
    ...(deps?.settings ?? DEFAULT_SETTINGS),
    defaultScope: scope,
  };
  const llm: LlmClient = deps?.llm
    ? safePreviewLlm(deps.llm)
    : { generateObject: unavailable("AI"), generateText: unavailable("AI") };

  const ctx: BlockContext = {
    runId: "preview",
    blockId: "preview",
    scope,
    settings,
    llm,
    agents: NO_AGENT_SERVICES, // only blocks without inputs are previewed; none of them use agents
    audit: {
      record: async (e) => ({
        ...e,
        id: "aud_preview",
        at: new Date().toISOString(),
        changes: e.changes ?? [],
      }),
    }, // previews aren't audited
    files,
    web: null,
    car: { add: unavailable("Adding to the car") },
    log: (m) => logs.push(m),
    progress: () => {},
    signal: new AbortController().signal,
    resumed: false,
  };

  let result;
  try {
    result = await registry.get(kind).run({}, params, ctx);
  } catch (err) {
    let message = err instanceof Error ? err.message : String(err);
    if (
      !(err instanceof AiPreviewError) &&
      /(\{"error"|api[_-]?key|bearer\s+[a-z0-9_-]+)/i.test(message)
    ) {
      message =
        "AI provider failed to generate a preview response. Check your AI settings and credentials.";
    }
    throw new ReqflowError("block_failed", message, { logs });
  }
  if (result.status !== "ok") throw new ReqflowError("block_failed", result.message, { logs });
  return { outputs: result.outputs, logs };
}
