+export function selectedClipboard(graph: WorkflowGraph, selectedIds: readonly string[]): WorkflowGraph | null {
+  const blocks = graph.blocks.filter((block) => selectedIds.includes(block.id) && !isBoundaryBlockKind(block.kind));
