+/** Size of a block before React Flow has measured it (BlockNode is w-56). */
+export const DEFAULT_BLOCK_SIZE = { width: 224, height: 120 };
+const GAP = 24;
+
+/** Find a free slot near the clicked canvas position without stacking existing blocks. */
+export function findFreePosition(graph: WorkflowGraph, measured: DataflowState["measured"], center: XY): XY {
+  const { width, height } = DEFAULT_BLOCK_SIZE;
+  const start = { x: center.x - width / 2, y: center.y - height / 2 };
+  const boxes = graph.blocks.map((block) => ({ x: block.position.x, y: block.position.y, ...(measured[block.id] ?? DEFAULT_BLOCK_SIZE) }));
+  const free = (point: XY) => boxes.every((box) => point.x + width + GAP <= box.x || box.x + box.width + GAP <= point.x || point.y + height + GAP <= box.y || box.y + box.height + GAP <= point.y);
+  for (let ring = 0; ring <= 12; ring++) for (let dy = -ring; dy <= ring; dy++) for (let dx = -ring; dx <= ring; dx++) {
+    if (Math.max(Math.abs(dx), Math.abs(dy)) !== ring) continue;
+    const point = { x: start.x + dx * (width + GAP), y: start.y + dy * (height + GAP) };
+    if (free(point)) return point;
+  }
+  return start;
+}
